import re
from html import escape, unescape
from guide_images import decorate
from play_recommendations import recommendations, stylesheet
from site_analytics import write_html

ROOT = Path(__file__).resolve().parents[1]
ROUTE = '/pokemon-battlegrounds/'
GAME = 'https://ranked.pokemonbattlegrounds.com/'


def build():
    nav = '<a href="#play">Play on original</a><a href="#start">Start here</a><a href="#which-game">Which game?</a><a href="#more-games">More games</a>'
    html = f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Pokémon Battlegrounds: Original Game &amp; Start Guide</title><meta name="description" content="Find PB Ranked, the Pokémon Battlegrounds browser game. Check its sign-in requirement, Auto and Manual controls, and the correct original-game link.">
<link rel="canonical" href="https://megabonk.org{ROUTE}"><meta property="og:type" content="website"><meta property="og:title" content="Pokémon Battlegrounds: Original Game &amp; Start Guide"><meta property="og:description" content="Find PB Ranked and check what you need before signing in."><meta property="og:url" content="https://megabonk.org{ROUTE}"><meta property="og:image" content="https://megabonk.org/assets/pokemon-battlegrounds/login-1280.webp">
<link rel="stylesheet" href="/assets/pokebonk/site.css"><link rel="stylesheet" href="/assets/guide-article-layout.css"><link rel="stylesheet" href="/assets/pokearena-2d/site.css"><link rel="stylesheet" href="/assets/pokemon-battlegrounds/site.css">
<script async src="https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client=ca-pub-8830315294299920" crossorigin="anonymous"></script></head>
<body class="guide-layout pa-guide pbg-guide"><a class="skip" href="#main">Skip to content</a><header class="top"><div class="wrap"><a class="brand" href="/"><span>Megabonk.org<small>Independent games &amp; guides</small></span></a><nav class="desktop-nav" aria-label="Main navigation">{nav}</nav><details class="mobile-nav"><summary>Menu</summary><nav class="mobile-links" aria-label="Mobile navigation">{nav}</nav></details></div></header>
<main class="wrap" id="main"><header class="pa-intro" id="guide"><div><p class="eyebrow">PB RANKED · INDEPENDENT START GUIDE</p><h1>Pokémon Battlegrounds</h1><p>The playable browser game from the Pokémon Battlegrounds animation channel is <strong>PB Ranked</strong>. Open <strong>ranked.pokemonbattlegrounds.com</strong> for real-time battles. The current client requires <strong>Discord or Google sign-in</strong>; the channel homepage is a different destination.</p><div id="play"><a class="pa-launch" href="{GAME}" target="_blank" rel="noopener noreferrer">Open PB Ranked on its original site ↗<span class="sr-only"> (opens in a new tab)</span></a><p class="pa-caption">Destination: ranked.pokemonbattlegrounds.com. The publisher blocks embedding, so the game opens in its own tab.</p></div><p class="pa-version">By Megabonk.org · Checked 5 November 2026 · Unofficial guide</p></div><!--PB_ENTRY_FIGURE--></header>
<article class="pa-notes"><nav class="pa-jump" aria-label="On this page"><a href="#start">Before your first battle</a><a href="#controls">Auto or Manual?</a><a href="#account">Account &amp; progress</a><a href="#which-game">Identify the game</a><a href="#sources">Sources</a></nav>
<section id="start"><h2>Start with the right account and mode</h2><p><strong>Start with an Easy practice battle to learn your team without risking rating.</strong> You will need to sign in before choosing your Pokémon and entering practice.</p><ol><li><strong>Open the ranked subdomain.</strong> If you see a gallery of animated battles or a Masters Eight ballot, you are on the channel website, not the PB Ranked client.</li><li><strong>Check whether you are returning.</strong> Existing players should sign in with the same Discord or Google account. New players are prompted to pick a trainer name of 2–16 characters and a trainer before signing in. Some trainer choices show rating or star requirements; do not assume every portrait is available immediately.</li><li><strong>Read the help before queuing.</strong> The top-bar <strong>?</strong> opens How battles work even on the sign-in screen. Use the controller icon to inspect current key bindings.</li><li><strong>After sign-in, prepare your team, then choose Practice vs bot → Easy.</strong> For the inspected 3v3 format, Your team shows three slots. Use the Pokémon list to fill your team and click a team member to inspect its moves. The practice chooser offers Easy, Casual, Normal, Hard and Hardest, with no rating on the line. Read the selected moves and try Auto before switching to Manual. Use <strong>Find battle</strong> when you intend to seek an opponent; practice is a separate button, not the Ranked/Unranked selector.</li></ol><p>If you cannot reach the team screen, use the original client’s help or choose <a href="#more-games">another browser game</a>. PB Ranked requires sign-in; a guest route has not been verified.</p></section>
<section id="controls"><h2>Choose Auto, called moves or full Manual control</h2><p>PB Ranked’s in-game help describes three control options. Try Auto first, then take over attacks or movement when you are ready.</p><div class="table-wrap" tabindex="0" role="region" aria-label="PB Ranked control choices"><table><thead><tr><th>Your choice</th><th>What the client says it does</th><th>What to do next</th></tr></thead><tbody><tr><td>Auto</td><td>Your Pokémon moves, dodges and chooses attacks itself. You can still call one of its four moves.</td><td>Watch cooldown and range. A glowing move button means ready and in range; a called move waits for the current attack to finish.</td></tr><tr><td>Auto movement, your attacks</td><td>Turning off <strong>Auto attacks for me</strong> keeps automatic movement and dodging, but attacks only when you call a move.</td><td>Look under your trainer settings after sign-in. This is a different choice from full Manual.</td></tr><tr><td>Manual</td><td>Press Auto to switch to Manual. You steer, call attacks and trigger Dodge yourself.</td><td>The inspected defaults show WASD movement, 1–4 moves and Space dodge. Read Controls if you change bindings.</td></tr></tbody></table></div><p>The help shows Z/X/C for bench switches and M for Mega Evolve or Greninja’s Battle Bond, when applicable. The client lists controller support and recommends landscape orientation on phones. Neither was tested on a physical device in our check.</p><p><strong>Leaving the tab is not a pause.</strong> The help says your team keeps fighting if you leave a match, and you lose if you are absent when it ends. Do not use tab switching as a pause strategy.</p></section>
<section id="account"><h2>Keep your account separate from other fan games</h2><p>The project’s privacy notice says PB Ranked keeps your trainer, rating, win/loss record and matches on its server, while settings, teams and a sign-in code use your browser’s local storage. It describes Discord/Google sign-in as sharing an account ID, rather than giving the game your password. </p><p>Return using the same sign-in provider and account. Do not assume that PB Ranked, Poké Arena 2D, Apex Arena or PokeBonk share trainers, teams, saves or ratings. The project says ratings may reset at a season boundary and that the game can change or stop during development.</p><p>For account or game issues, use <strong>Report a problem</strong> in the original client, or <a href="mailto:stinsonoscar@gmail.com">PB Ranked developer email ↗</a>. Do not send passwords or sign-in codes. Megabonk.org cannot recover an original-game account.</p></section>
<section id="which-game"><h2>Which Pokémon battle project did you mean?</h2><div class="table-wrap" tabindex="0" role="region" aria-label="Identify Pokémon Battlegrounds and separate fan games"><table><thead><tr><th>Project</th><th>Recognize the destination</th><th>Use this route</th></tr></thead><tbody><tr><td>PB Ranked</td><td>ranked.pokemonbattlegrounds.com; real-time browser battles from the animation channel.</td><td><a href="#play">Original-game launch above</a></td></tr><tr><td>Pokémon Battlegrounds channel</td><td>pokemonbattlegrounds.com; animated match gallery and voting, rather than the ranked client.</td><td><a href="https://pokemonbattlegrounds.com/" target="_blank" rel="noopener noreferrer">Pokémon Battlegrounds · channel website ↗</a></td></tr><tr><td>Pokémon Apex Arena</td><td>pokemonapexarena.com; its creator explicitly describes a separate fan project inspired by the Battlegrounds videos.</td><td><a href="https://pokemonapexarena.com/" target="_blank" rel="noopener noreferrer">Pokémon Apex Arena · separate project ↗</a></td></tr><tr><td>Poké Arena 2D</td><td>pokearena2d.com; a separate arena game with its own Training setup, controls and progress.</td><td><a href="/pokearena-2d/">Original game &amp; Training guide</a></td></tr><tr><td>PokeBonk / PokéSurvivor</td><td>Pokémon-themed survival games with hordes and run progression, rather than this ranked client.</td><td><a href="/pokebonk/play/">PokeBonk</a> · <a href="/poke-survivor/play/">PokéSurvivor</a></td></tr></tbody></table></div><p>Apex Arena’s creator identifies it as a separate project inspired by the channel. Use the destination above to avoid following another game’s controls or account instructions.</p></section>
<section class="sources" id="sources"><h2>Sources &amp; checks</h2>
<p>Checked 5 November 2026: sign-in, in-game help, team selection and an Easy practice battle through its result screen. Gameplay instructions follow the client’s help; competitive performance and account transfer were not tested. The development build showed no version number.</p>
<ul>
<li><a href="{GAME}" target="_blank" rel="noopener noreferrer">PB Ranked ↗</a> — game entry, controls and practice options.</li>
<li><a href="https://www.youtube.com/watch?v=23gz_hdNsrc" target="_blank" rel="noopener noreferrer">Creator’s announcement ↗</a> — identifies the ranked game; 30 October 2026.</li>
<li><a href="{GAME}privacy" target="_blank" rel="noopener noreferrer">PB Ranked privacy ↗</a> / <a href="{GAME}terms" target="_blank" rel="noopener noreferrer">terms ↗</a> — account storage and season resets; updated 1 November / 29 October 2026.</li>
<li><a href="https://pokemonapexarena.com/" target="_blank" rel="noopener noreferrer">Apex Arena ↗</a> — creator’s statement that it is a separate project.</li>
</ul></section></article>
{recommendations('pokemon-battlegrounds')}
</main><footer class="footer"><div class="wrap footer-grid"><div><strong>Find your next game.</strong><p>Independent editorial by Megabonk.org. The original project operates the game and its services.</p><a href="/#wiki-start">More games &amp; guides →</a></div><nav aria-label="Site information"><a href="/about/">About</a><a href="/contact/">Contact</a><a href="/privacy-policy#pokemon-battlegrounds">Privacy</a></nav></div></footer></body></html>'''
    target = ROOT / 'pokemon-battlegrounds/index.html'
    target.parent.mkdir(exist_ok=True)
    html = decorate(ROUTE, stylesheet(html))
    figure = re.search(r'<figure class="game-image.*?</figure>', html, re.S)
    assert figure, 'PB Ranked requires its reviewed login figure'
    html = html[:figure.start()] + html[figure.end():]
    html = html.replace('<!--PB_ENTRY_FIGURE-->', figure[0], 1)
    # Give every external text link an accessible destination/new-tab description.
    def accessible_link(match):
        tag, text = match.groups()
        if 'target="_blank"' not in tag or 'aria-label=' in tag or 'sr-only' in text:
            return match[0]
        label = escape(unescape(text).strip() + ' (external website, opens in a new tab)', quote=True)
        return tag[:-1] + f' aria-label="{label}">' + text + '</a>'
    html = re.sub(r'(<a\b[^>]*>)([^<]*(?:<span[^>]*>.*?</span>)?)</a>', accessible_link, html)
    write_html(target, html, encoding='utf-8')
    target = ROOT / 'index.html'
    html = target.read_text(encoding='utf-8')
    if 'id="pokemon-battlegrounds-game-entry"' not in html:
        html = html.replace('<div class="route-grid">', '<div class="route-grid"><a class="route-card" id="pokemon-battlegrounds-game-entry" href="/pokemon-battlegrounds/"><h3>Pokémon Battlegrounds</h3><p>Find PB Ranked on its original site. Check the sign-in requirement, Auto/Manual choices and separate fan-game identities.</p><span class="route-link">Original game &amp; start guide →</span></a>', 1)
        write_html(target, html, encoding='utf-8')
    target = ROOT / 'privacy-policy.html'
    html = target.read_text(encoding='utf-8')
    if 'id="pokemon-battlegrounds"' not in html:
        html = html.replace('</body>', '<h2 id="pokemon-battlegrounds">Pokémon Battlegrounds external game links</h2><p>Updated 5 November 2026. Our guide opens ranked.pokemonbattlegrounds.com in a new tab. The publisher prohibits remote embedding; this guide does not load its game client, handle its sign-in, or provide an account/save service. Following the link connects you to the original project and any login provider you choose there, under their own policies. Screenshots on this guide are local files. The guide inherits the site’s existing AdSense and site-wide Umami integrations described above.</p></body>', 1)
        write_html(target, html, encoding='utf-8')
    print('Built PB Ranked original-host entry and root/privacy links.')


if __name__ == '__main__':
    build()
